import { mkdir, writeFile } from "node:fs/promises";

const manuals = {
  en: {
    title: "ImmunoStudio user manual",
    subtitle: "Detailed English guide · version 0.2 · 2 November 2026",
    other: "Nederlandse handleiding",
    print: "Print / save as PDF",
    contents: "Contents",
    back: "Open ImmunoStudio",
    sections: [
      [
        "start",
        "1. Start and understand your workspace",
        `<p>Open <a href="https://espierin.github.io/immunostudio/">ImmunoStudio online</a>, or start the local version with <code>Start-ImmunoStudio.cmd</code>. The local address is normally <code>http://127.0.0.1:5180/</code>. The local version adds native Office and video exporters.</p><p>New projects start in <b>2D</b>, with the <b>Default</b> illustration style. English is the initial interface language. A previously selected language is remembered. Choose English or Nederlands in the header; this does not translate text inside your illustration or change your object names.</p><ul><li><b>Header:</b> project name, global Labels switch, 2D/3D switch, language, New, Open, Project and Export.</li><li><b>Left:</b> library, search, categories and import (+).</li><li><b>Centre:</b> the drawing page in 2D; a rotatable scene and timeline in 3D.</li><li><b>Right:</b> Properties and, in 2D, Drawing. Hover over icons for explanations.</li></ul><p>2D and 3D are separate parts of the same project. Switching modes keeps your work but does not automatically convert or add objects. A new 3D scene has no membrane until you explicitly add one.</p>`,
      ],
      [
        "quick",
        "2. First illustration: step by step",
        `<ol><li>Enter a meaningful project name in the header.</li><li>Stay in 2D. Search the Basic elements library, or select a category.</li><li>Click an element card to place it on the page.</li><li>Choose Select or Move and drag it to the desired position.</li><li>Use a corner handle to resize it. Use the round handle above the selection, or Rotate, to change its angle.</li><li>Open Properties to enter exact X/Y, width, height and rotation values.</li><li>Add a text label with Text; click the page, then edit the text in Properties.</li><li>Choose an illustration style in Properties → Illustration style.</li><li>Click Project to download an editable backup, then Export for the finished figure.</li></ol><p>The library contains 190 curated individual elements, rather than complete teaching figures or tables. Search terms may be Dutch or English; source titles are retained.</p>`,
      ],
      [
        "select",
        "3. Select, move, resize and arrange in 2D",
        `<p>Click an element to select it. Shift-click to add or remove objects from the selection. Drag an empty area with Select to make a selection rectangle. A grouped element selects its group. Use Drawing → Select all, Deselect all, Invert selection or Unlocked objects for larger selections.</p><p>Move by dragging, by entering X/Y in Properties, or with the arrow keys. Arrow keys move one page unit; Shift+arrow moves ten. Rotate by dragging around the selection with Rotate, using the round rotation handle, or entering an angle in degrees. Shift constrains interactive rotation to 15° increments. Drawing also offers 90° left/right commands.</p><p>Library SVG elements keep their proportions when resized with corner handles. Shift also constrains resizing of other shapes. Exact width/height fields are available in Properties. If movement appears to jump, turn off Snap to grid in Drawing.</p><table><tr><th>Drawing control</th><th>Use</th></tr><tr><td>Copy / Paste / Duplicate</td><td>Reuse selected elements within the editor. Duplicate places a copy slightly offset.</td></tr><tr><td>Group / Ungroup</td><td>Select and move related elements together.</td></tr><tr><td>To front / To back / Raise / Lower</td><td>Change the stacking order of overlapping objects.</td></tr><tr><td>Left / Centre X / Right / Top / Centre Y / Bottom</td><td>Align selected objects. Rotation is retained.</td></tr><tr><td>Distribute X / Y</td><td>Space at least three objects with equal gaps.</td></tr><tr><td>Page width, height and colour</td><td>Set the output page rather than the size of an individual object.</td></tr></table><p>Properties → Locked prevents editing until you unlock the object. Use the scene list in Properties to select objects hidden behind others and to toggle visibility. Fit page restores the normal page view; Pan, zoom buttons and the mouse wheel change your view, not your artwork size.</p>`,
      ],
      [
        "draw",
        "4. Text, shapes and labels",
        `<p>Choose Text and click to place a label. Select it and edit its content, font size and colour in Properties. Draw Line, Arrow, Rectangle or Ellipse by dragging from a starting point to an ending point. Draw creates a freehand line. Properties exposes the relevant appearance controls for each object, such as fill, stroke, opacity and line width.</p><p>The global <b>Labels</b> checkbox switches illustration labels off or on for both display and export. Use it to make labelled and unlabelled versions without deleting the labels. A 3D object also has its own Show label option. Source text inside imported vector illustrations is not automatically translated when you change interface language.</p><p>Cells in 2D can have soft volume shading. Select a cell and use Volume shading in Properties to change that appearance. This is a vector shading effect; the separate 3D cell variant has actual depth.</p>`,
      ],
      [
        "nodes",
        "5. Edit the points of a basic SVG element",
        `<ol><li>Add an SVG basic element and select it.</li><li>Open Drawing and choose <b>Edit nodes</b>.</li><li>Click the particular part you want to reshape: for example a cell outline, nucleus or molecular domain. An SVG can contain several independent parts.</li><li>Drag blue anchor points to move the contour; drag orange Bézier handles to change curvature.</li><li>Select a point and choose <b>Add node</b> to split the corresponding line or Bézier segment. The split initially preserves the curve.</li><li>Return to Select to move the whole element. Use Undo if a contour changes unexpectedly.</li></ol><p>The editor changes the embedded project copy and preserves the original library file. Existing transforms and other SVG parts are retained. Line, quadratic and cubic segments can be split. SVG arc endpoints can move, but arc splitting and a complete Inkscape-style node editor are not implemented. These controls edit vector illustration geometry, not atoms or a protein sequence.</p>`,
      ],
      [
        "membrane",
        "6. Draw membranes and convert a circle into a vesicle",
        `<h3>Draw a membrane directly</h3><ol><li>In 2D choose Membrane and drag across the page.</li><li>Select the resulting bilayer.</li><li>Drag its anchor points and orange handles to bend it.</li><li>Use Properties to change membrane thickness.</li><li>Choose Add curve point, or double-click the membrane, to add an anchor without initially changing the existing curve.</li></ol><h3>Convert a drawn shape</h3><ol><li>Draw a line, freehand path, rectangle, circle or ellipse. For a circle, give an ellipse equal width and height in Properties.</li><li>Select the shape and open Drawing.</li><li>Click <b>Convert to membrane</b>.</li><li>An open path becomes a membrane segment. A closed shape becomes a bilayer loop with an empty centre: a 2D vesicle.</li><li>Adjust the curve and thickness. Undo restores the original drawing.</li></ol><p>To create a spatial version, switch to 3D and click <b>3D from 2D drawing</b> in Properties. This converts eligible SVG elements and membranes on the 2D page. A closed membrane becomes an ellipsoidal vesicle cutaway with two shells and lipid tails at the opening rim. Irregular closed loops currently use their bounding ellipse in 3D; their original 2D contour remains intact. Very long freehand paths are simplified when converted.</p>`,
      ],
      [
        "three",
        "7. Work with 3D cells and molecules",
        `<p>Switch to 3D. Add a basic element for a rounded schematic volume, choose a built-in model under 3D models, import your own model, or use 3D from 2D drawing. Add vesicle creates a separate vesicle without adding a planar membrane.</p><p>Drag empty space to orbit the camera, right-drag to pan and use the wheel to zoom. Select an object and choose Focus selection to place the camera target on it. Default view restores the standard view. Properties → Camera &amp; focus offers front/back/side/top/bottom views, orthographic or perspective projection and numeric zoom.</p><p>Use Move and the 3D handles, or enter X/Y/Z in Properties. Use Rotate and the rotation controls; additional X/Y rotations are in radians, while the displayed main rotation angle is in degrees. Scale is illustrative. Depth layer offers four preset levels plus free depth. A membrane-anchored model instead has a Position along membrane control and a depth position.</p><p>Cell volumes have a smooth hemispherical back and a flat front cut showing the original nucleus and organelles. Volume depth changes their depth. Rounded volume and relief are schematic geometry options for SVG-derived models. They are not predictions of a protein's atomic structure.</p><p>Use Save to my library to reuse a model on this browser/device. GLB export is available for supported selected 3D models. A 3D variant remains linked to its 2D source ID to avoid duplicates; later edits to the 2D source do not automatically rebuild an existing 3D variant. To regenerate one, remove that 3D variant and run the conversion again.</p>`,
      ],
      [
        "three-membrane",
        "8. Add and edit the 3D membrane",
        `<p>Enable Properties → Membrane → Show membrane, or choose the Membrane tool. A new scene leaves it off by default. Thickness, depth and rear fading control its appearance. Lipid heads cover the membrane surfaces; paired thin tails are shown at the physical outside perimeter rather than throughout the interior depth.</p><p>Choose Edit Bézier curve to expose anchors and handles. Drag them to bend the membrane. Add curve point splits the curve; anchored proteins follow its shape. Cross-section changes the visible cut. A membrane edge can look thin from a side or top view; rotate the camera to inspect it.</p><p>For supported proteins or imported structures, Attach to membrane / Detach from membrane switches anchoring. Imported models use their model origin as the manual anchor: inspect orientation, scale and the transmembrane boundary yourself. The reference channel has a membrane opening; arbitrary imported models do not automatically cut a matching pore.</p><p>Conformation is a schematic IgG hinge tool: select an IgG, choose Conformation, select its Fab arm and adjust the hinge angle. This is not general protein rigging or molecular dynamics.</p>`,
      ],
      [
        "pdb",
        "9. Import SVG, GLB, PDB and mmCIF",
        `<p>Click + in the library. In 2D import a self-contained SVG. In 3D import SVG, GLB, PDB, CIF or mmCIF. Files are limited to 30 MB. Use independent vector SVGs without scripts or external images. A 3D SVG import initially remains a flat asset; use Build 3D volume when that control is offered.</p><h3>Retrieve a structure from RCSB PDB</h3><ol><li>In 3D select the PDB library tab and search by molecule name or PDB ID.</li><li>Open a result. Choose biological assembly 1 or the asymmetric unit.</li><li>Fetch the structure. If the assembly is unavailable, try the asymmetric unit.</li><li>Inspect the rotating preview and select only the required chains.</li><li>Choose van der Waals atom spheres or CA/P backbone.</li><li>Add the selected chains, then check scale, orientation and any membrane anchor.</li></ol><p>Some basic molecules have an Experimental structure panel with a checked PDB reference and an RCSB link. References can be fragments, complexes or a related species/isotype. Check species, allele, peptide and chain composition before using them. A reference is not an automatic exact identity match to the cartoon. Other molecules offer RCSB search.</p><p>Coordinates are converted from Å to nm. Missing domains are not reconstructed. The app does not simulate molecular dynamics or calculate a molecular solvent surface. RCSB search and retrieval require internet; imported project coordinates are stored with the project.</p>`,
      ],
      [
        "styles",
        "10. Illustration styles",
        `<p>Open Properties → Illustration style. The order is Default, UMC Utrecht, Nordic Light, Nordic Dark, EFI, Illustrated Light and Dark Presentation. Default is used for new projects. Styles alter illustration colours; the application interface retains its UMC Utrecht appearance.</p><p>Colour swatches let you adjust roles such as heads, tails, receptors, HLA, antibodies, background and labels. Individual colour overrides may take precedence; use Style colour to return an object to its style role. Import and JSON export allow stylesheet reuse. Save the project after creating a custom palette.</p>`,
      ],
      [
        "animate",
        "11. Animate a moving molecule: complete example",
        `<ol><li>In 3D add and select a molecule. Set Duration to 8 seconds.</li><li>Open Properties → <b>Animation &amp; render</b>. Choose 24 fps, Start frame 1 and End frame 192.</li><li>Choose <b>Selected object</b> as Keyframe target. Keep Auto keying off while setting up the first poses.</li><li>Move the timeline to time 0. Set the molecule's starting position and click Insert keyframe.</li><li>Move the timeline to time 4 seconds. Move or rotate the molecule, then click Insert keyframe again.</li><li>Click Play. The molecule moves between the poses; values are automatically calculated between keys.</li><li>Scrub the timeline to inspect intermediate frames.</li><li>In the key list, change a key's frame number to retime it, select its interpolation or click × to delete it.</li></ol><p><b>Important:</b> move the timeline first, then change the pose, then insert the key. Scrubbing evaluates existing keys and can replace an unkeyed pose. After setup, Auto keying records subsequent interactive camera/object transformations. Explicitly insert a key after other property changes when you need a guaranteed pose.</p><table><tr><th>Interpolation</th><th>Result</th></tr><tr><td>Constant</td><td>Hold the earlier pose until the next key.</td></tr><tr><td>Linear</td><td>Change values at a constant rate between keys.</td></tr><tr><td>Smooth · Bézier</td><td>Ease into and out of the movement.</td></tr></table><p>The interpolation on a key controls its outgoing segment. This is a Blender-like keyframe workflow with smooth easing, not Blender's full editable F-curve, NLA, constraint or rigging system. Object paths are determined by their keyed positions; no collision avoidance or physical movement is simulated.</p>`,
      ],
      [
        "camera",
        "12. Camera actions and combined animation",
        `<p>Choose Camera only as the target to keyframe the view without recording object poses. At the starting time, orbit/pan/zoom to the first view and insert a key. Move the timeline, change the view and insert another. Selected-object tracks and camera tracks can coexist. Scene and camera records all object poses and the view together; use independent targets when you want independent timing.</p><p>Focus selection establishes a target. Camera &amp; focus → Follow-me moves the camera with its anchor; Look at focus aims at the anchor; Free camera removes that following behaviour.</p><table><tr><th>Camera action</th><th>Generated motion over the render range</th></tr><tr><td>Orbit 360°</td><td>One complete orbit around the current camera target.</td></tr><tr><td>Dolly towards focus</td><td>Move the camera halfway towards the target.</td></tr><tr><td>Zoom towards focus</td><td>Double the camera zoom without a dolly movement.</td></tr><tr><td>Pan horizontally</td><td>Move camera and target together horizontally.</td></tr><tr><td>Rotate object 360°</td><td>Create a full-turn animation for the selected object.</td></tr></table><p>Set the view, target and render range before creating an action. A camera action replaces camera-only keys within that range, while object tracks remain. Use Undo to restore previous keys. Loop repeats playback over the render range. Frame 1 corresponds to time zero; at 24 fps, frame 97 corresponds to 4 seconds.</p>`,
      ],
      [
        "export",
        "13. Export for figures, Office and video",
        `<p>First download an editable Project backup. Exported images and videos are finished outputs, not substitutes for the project. Set the style and Labels switch before export.</p><table><tr><th>Format</th><th>Recommended use and availability</th></tr><tr><td>PNG</td><td>Online/local. Raster figure at 1920 or 3840 px wide; optional transparent background. 2D exports the page; 3D renders the current view.</td></tr><tr><td>SVG</td><td>Online/local. Entire native 2D page. In 3D it exports the selected source vector, not the entire rendered scene.</td></tr><tr><td>EMF / WMF</td><td>Local Inkscape exporter. Useful for PowerPoint/Word. 2D remains vector where supported; 3D embeds a raster image.</td></tr><tr><td>MP4 / AVI</td><td>Local FFmpeg exporter. MP4 uses H.264; AVI uses Motion JPEG. Render settings control range, rate and dimensions.</td></tr><tr><td>GIF</td><td>Local. 12 fps, 800 px wide, maximum 15 seconds, looping.</td></tr><tr><td>WebM</td><td>Online/local if the browser supports recording. Real-time recording; keep the tab active for reliable capture.</td></tr><tr><td>PNG frame sequence</td><td>Online/local. ZIP with a numbered image for every selected output frame, suitable for external video editing.</td></tr></table><p><b>Fonts:</b> EMF/WMF can convert text to vector outlines. This preserves letter appearance but does not embed editable fonts. Keep the source project for text editing. Office versions may simplify gradients; SVG or PNG can be preferable when appearance is more important than metafile editing.</p><h3>Render settings</h3><ol><li>In Animation &amp; render, choose 12, 24, 25, 30, 50 or 60 fps.</li><li>Set Start frame, End frame and Frame step. Use step 1 for every frame.</li><li>Set render width (320–3840) and height (240–2160). Use even dimensions for conventional video encoders.</li><li>Open Export and verify the settings. Choose PNG sequence, WebM or a local video format.</li><li>Wait for completion; use Cancel when the progress panel offers it.</li></ol><p>Maximum output is 1801 frames per job. Frame steps above 1 omit frames: PNG filenames retain their original frame numbers, while encoded playback uses the selected fps and therefore becomes shorter. PNG and native video render chosen frames individually; WebM records in real time. Video settings do not change the separate still-image size selector.</p><p>On GitHub Pages, disabled native export buttons are expected. Transfer a downloaded .immuno project to the local version for EMF/WMF or MP4/AVI/GIF. In Word or PowerPoint, insert the exported file using Insert → Pictures, or Insert → Video for a supported movie format.</p>`,
      ],
      [
        "save",
        "14. Save, reopen and transfer projects",
        `<p>The editor automatically saves in browser storage on the current device. Wait for the saved indicator. This is not a cloud account or a shared project folder. Online and local versions have separate browser storage; another browser or device will not automatically see your project.</p><ol><li>Click Project to download an editable <code>.immuno</code> file.</li><li>Keep versioned copies before major edits.</li><li>Use Open and select that file to restore it, including embedded assets and animation keys.</li><li>To transfer between online and local versions, download from one and open in the other.</li><li>Before choosing New and starting an empty scene, download the current project if you want to keep it separately.</li></ol><p>Clearing browser/site data can remove autosaves and the personal model library. File backups remain your portable copy. Use Undo/Redo for recent edits; the undo history is limited and is not a version archive.</p>`,
      ],
      [
        "shortcuts",
        "15. Keyboard reference",
        `<table><tr><th>Shortcut</th><th>Action</th></tr><tr><td>Ctrl/Cmd+Z</td><td>Undo</td></tr><tr><td>Ctrl/Cmd+Shift+Z</td><td>Redo</td></tr><tr><td>Ctrl/Cmd+A</td><td>Select all in 2D</td></tr><tr><td>Ctrl/Cmd+C / V / D</td><td>Copy / paste / duplicate in 2D</td></tr><tr><td>Ctrl/Cmd+G / Shift+Ctrl/Cmd+G</td><td>Group / ungroup in 2D</td></tr><tr><td>Arrow / Shift+arrow</td><td>Move 2D selection 1 / 10 units</td></tr><tr><td>Delete</td><td>Delete selection when the drawing/scene has focus</td></tr><tr><td>Escape</td><td>Close a dialog; in 2D also return to Select and deselect</td></tr></table><p>Shortcuts generally do not act on the drawing while you are typing in a text, number or selection field. Click the page or scene first.</p>`,
      ],
      [
        "troubleshoot",
        "16. Troubleshooting and limits",
        `<dl><dt>I cannot move an element.</dt><dd>Check the active mode and tool. Select the object, unlock it in Properties, and use Move. In 3D, empty-space dragging rotates the camera.</dd><dt>I cannot find a hidden element.</dt><dd>Use the scene list in Properties, enable its visibility and adjust its stacking/depth order.</dd><dt>My 2D drawing is absent in 3D.</dt><dd>Switching modes does not convert it. Use 3D from 2D drawing. Only eligible vectors and membranes are converted; plain text and native primitive shapes are not all converted directly.</dd><dt>A 3D variant does not reflect my newest 2D edits.</dt><dd>Existing variants are retained. Delete that variant and regenerate from the updated 2D source.</dd><dt>The membrane is missing.</dt><dd>Enable Show membrane in 3D, or draw/convert a membrane in 2D. The two modes have separate membrane content.</dd><dt>Animation jumps or a pose disappears.</dt><dd>Check keyframe target, key timing and interpolation. Insert the starting pose and each edited pose. Scrubbing evaluates saved keys; use Undo to recover an unkeyed edit.</dd><dt>A PDB structure has extra copies.</dt><dd>Review assembly choice and chain selection. Import only the needed chains. Do not assume every chain is part of your intended illustration.</dd><dt>A native exporter is unavailable.</dt><dd>Use the local starter and ensure its Inkscape/FFmpeg support is available. Online, use SVG/PNG, WebM or PNG frames.</dd><dt>Everything looks slow.</dt><dd>Reduce the number of complex volumes or imported atoms, use backbone representation and export a short low-resolution range first.</dd></dl><p>All 190 basic elements have been checked for valid finite 3D geometry, but their schematic volumes do not establish biological identity. No automatic missing-region reconstruction, full molecular surface computation, general rigging or molecular dynamics is provided.</p>`,
      ],
    ],
  },
  nl: {
    title: "ImmunoStudio gebruikershandleiding",
    subtitle: "Uitgebreide Nederlandse handleiding · versie 0.2 · 2 november 2026",
    other: "English manual",
    print: "Afdrukken / opslaan als PDF",
    contents: "Inhoud",
    back: "ImmunoStudio openen",
    sections: [
      [
        "start",
        "1. Starten en de werkruimte begrijpen",
        `<p>Open <a href="https://espierin.github.io/immunostudio/">ImmunoStudio online</a> of start de lokale versie met <code>Start-ImmunoStudio.cmd</code>. Het lokale adres is doorgaans <code>http://127.0.0.1:5180/</code>. De lokale versie biedt extra exportmogelijkheden voor Office en video.</p><p>Nieuwe projecten starten in <b>2D</b> met illustratiestijl <b>Default</b>. Engels is de aanvankelijke interfacetaal; een eerder gekozen taal wordt onthouden. Kies Nederlands of English in de kopbalk. Dit vertaalt geen tekst in je illustratie en verandert geen eigen objectnamen.</p><ul><li><b>Kopbalk:</b> projectnaam, algemene schakelaar Labels, 2D/3D, taal, Nieuw, Openen, Project en Exporteren.</li><li><b>Links:</b> bibliotheek, zoeken, categorieën en importeren (+).</li><li><b>Midden:</b> tekenblad in 2D; draaibare scène en tijdlijn in 3D.</li><li><b>Rechts:</b> Eigenschappen en, in 2D, Tekenen. Houd de muis boven pictogrammen voor uitleg.</li></ul><p>2D en 3D zijn afzonderlijke onderdelen van hetzelfde project. Wisselen van modus bewaart je werk, maar converteert of voegt niet automatisch objecten toe. Een nieuwe 3D-scène bevat geen membraan totdat je dit zelf toevoegt.</p>`,
      ],
      [
        "quick",
        "2. Je eerste illustratie: stap voor stap",
        `<ol><li>Geef het project een herkenbare naam in de kopbalk.</li><li>Blijf in 2D. Zoek in Basis set of kies een categorie.</li><li>Klik op een bibliotheekkaart om het element op het blad te plaatsen.</li><li>Kies Selecteren of Verplaatsen en sleep het element naar de gewenste plek.</li><li>Verander de grootte met een hoekgreep. Draai met de ronde greep boven de selectie of met Draaien.</li><li>Open Eigenschappen voor exacte X/Y, breedte, hoogte en rotatie.</li><li>Voeg met Tekst een label toe: klik op het blad en bewerk de tekst in Eigenschappen.</li><li>Kies de illustratiestijl onder Eigenschappen → Stylesheet.</li><li>Klik op Project voor een bewerkbare reservekopie en daarna op Exporteren voor het eindresultaat.</li></ol><p>De bibliotheek bevat 190 geselecteerde losse basiselementen, geen volledige lesfiguren of tabellen. Zoeken kan met Nederlandse of Engelse termen; oorspronkelijke titels blijven behouden.</p>`,
      ],
      [
        "select",
        "3. Selecteren, verplaatsen, schalen en ordenen in 2D",
        `<p>Klik op een element om het te selecteren. Met Shift-klik voeg je objecten toe aan de selectie of verwijder je ze eruit. Sleep met Selecteren over een leeg gebied voor een selectiekader. Een gegroepeerd object selecteert zijn groep. Gebruik in Tekenen ook Alles selecteren, Niets selecteren, Selectie omkeren of Onvergrendeld.</p><p>Verplaats door te slepen, met X/Y in Eigenschappen of met de pijltjestoetsen. Een pijltje verplaatst één bladeenheid; Shift+pijltje tien. Draai door met Draaien rond de selectie te slepen, met de ronde rotatiegreep of door een hoek in graden in te vullen. Shift beperkt interactief draaien tot stappen van 15°. Tekenen biedt ook 90° linksom en rechtsom.</p><p>SVG-bibliotheekelementen behouden hun verhouding bij schalen met hoekgrepen. Shift begrenst ook het schalen van andere vormen. Exacte breedte en hoogte staan in Eigenschappen. Springt een object tijdens slepen, schakel dan Op raster uitlijnen uit in Tekenen.</p><table><tr><th>Bediening in Tekenen</th><th>Gebruik</th></tr><tr><td>Kopiëren / Plakken / Dupliceren</td><td>Hergebruik binnen de editor. Dupliceren plaatst een iets verschoven kopie.</td></tr><tr><td>Groeperen / Losmaken</td><td>Verwante elementen samen selecteren en verplaatsen.</td></tr><tr><td>Vooraan / Achteraan / Vooruit / Achteruit</td><td>De stapelvolgorde van overlappende objecten aanpassen.</td></tr><tr><td>Links / Midden X / Rechts / Boven / Midden Y / Onder</td><td>Selectie uitlijnen met behoud van rotatie.</td></tr><tr><td>Verdelen X / Y</td><td>Minstens drie objecten met gelijke tussenruimten verdelen.</td></tr><tr><td>Bladbreedte, bladhoogte en bladkleur</td><td>Het uitvoerblad instellen, niet de grootte van één object.</td></tr></table><p>Vergrendeld in Eigenschappen voorkomt bewerkingen totdat je ontgrendelt. Gebruik de scènelijst in Eigenschappen voor objecten achter andere elementen en voor zichtbaarheid. Pas blad herstelt de normale bladweergave. Pan, zoomknoppen en het muiswiel wijzigen alleen je zicht, niet de grootte van je illustratie.</p>`,
      ],
      [
        "draw",
        "4. Tekst, vormen en labels",
        `<p>Kies Tekst en klik om een label te plaatsen. Selecteer het en pas inhoud, lettergrootte en kleur aan in Eigenschappen. Teken Lijn, Pijl, Kader of Ellips door van begin- naar eindpunt te slepen. Tekenen maakt een vrije lijn. Eigenschappen toont passende instellingen zoals vulling, lijnkleur, dekking en lijndikte.</p><p>De algemene schakelaar <b>Labels</b> zet illustratielabels aan of uit, zowel op het scherm als in de export. Zo maak je een versie met en zonder labels zonder tekst te verwijderen. Een 3D-object heeft daarnaast Label tonen. Tekst in geïmporteerde vectorfiguren wordt niet automatisch vertaald bij een andere interfacetaal.</p><p>2D-cellen kunnen zachte volumekleuring hebben. Selecteer een cel en wijzig Volumewerking in Eigenschappen. Dit is een vectorkleureffect; de aparte 3D-celvariant heeft werkelijke diepte.</p>`,
      ],
      [
        "nodes",
        "5. Punten van een SVG-basiselement bewerken",
        `<ol><li>Voeg een SVG-basiselement toe en selecteer het.</li><li>Open Tekenen en kies <b>Punten bewerken</b>.</li><li>Klik op het specifieke onderdeel dat je wilt vervormen, bijvoorbeeld de celrand, kern of een moleculair domein. Eén SVG kan uit meerdere onderdelen bestaan.</li><li>Sleep blauwe ankerpunten om de contour te verplaatsen en oranje Bézier-handvatten om de kromming te veranderen.</li><li>Selecteer een punt en kies <b>Punt toevoegen</b> om het bijbehorende lijn- of Béziersegment te splitsen. De bestaande kromme blijft aanvankelijk gelijk.</li><li>Kies Selecteren om het hele element weer te verplaatsen. Gebruik Ongedaan maken bij een ongewenste verandering.</li></ol><p>Je bewerkt de ingesloten projectkopie; het oorspronkelijke bibliotheekbestand blijft intact. Transformaties en andere SVG-onderdelen blijven behouden. Rechte, kwadratische en kubische segmenten kunnen worden gesplitst. Eindpunten van SVG-bogen kunnen bewegen; bogen splitsen en een volledige Inkscape-punteneditor zijn niet geïmplementeerd. Je bewerkt de vectortekening, geen atomen of eiwitsequentie.</p>`,
      ],
      [
        "membrane",
        "6. Membranen tekenen en een cirkel omzetten naar een vesikel",
        `<h3>Direct een membraan tekenen</h3><ol><li>Kies in 2D Membraan en sleep over het blad.</li><li>Selecteer de ontstane lipidendubbellaag.</li><li>Buig het membraan met de ankerpunten en oranje handvatten.</li><li>Pas de membraandikte aan in Eigenschappen.</li><li>Kies Punt toevoegen of dubbelklik op het membraan voor een extra anker zonder de bestaande kromme aanvankelijk te vervormen.</li></ol><h3>Een getekende vorm omzetten</h3><ol><li>Teken een lijn, vrije lijn, rechthoek, cirkel of ellips. Maak voor een cirkel de breedte en hoogte van een ellips gelijk in Eigenschappen.</li><li>Selecteer de vorm en open Tekenen.</li><li>Klik op <b>Omzetten naar membraan</b>.</li><li>Een open pad wordt een membraansegment. Een gesloten vorm wordt een dubbellaags lus met een leeg centrum: een 2D-vesikel.</li><li>Pas kromming en dikte aan. Ongedaan maken herstelt de oorspronkelijke vorm.</li></ol><p>Voor de ruimtelijke versie: wissel naar 3D en kies <b>3D uit 2D-tekening</b> in Eigenschappen. Dit zet geschikte SVG-elementen en membranen op het blad om. Een gesloten membraan wordt een ellipsoïde vesikeldoorsnede met twee schillen en lipidestaarten bij de openingsrand. Onregelmatige gesloten vormen gebruiken in 3D momenteel hun omhullende ellips; de oorspronkelijke 2D-contour blijft behouden. Zeer lange vrije lijnen worden bij omzetting vereenvoudigd.</p>`,
      ],
      [
        "three",
        "7. Werken met 3D-cellen en moleculen",
        `<p>Wissel naar 3D. Voeg een basiselement toe voor een afgerond schematisch volume, kies een ingebouwd 3D-model, importeer een eigen model of gebruik 3D uit 2D-tekening. Vesikel toevoegen maakt een los vesikel zonder een vlak membraan toe te voegen.</p><p>Sleep over lege ruimte om de camera te draaien, sleep met rechts om te verschuiven en zoom met het muiswiel. Selecteer een object en kies Focus selectie om het cameradoel erop te zetten. Standaardzicht herstelt het beginzicht. Onder Camera &amp; focus vind je voor-/achter-/zij-/boven-/onderaanzichten, orthografische of perspectivische projectie en numerieke zoom.</p><p>Gebruik Verplaatsen en de 3D-grepen of X/Y/Z in Eigenschappen. Gebruik Draaien en de rotatievelden. De extra X/Y-rotaties zijn in radialen; de getoonde hoofdrotatie is in graden. De schaal is illustratief. Diepteniveau biedt vier vaste niveaus en vrije diepte. Een membraangekoppeld model heeft in plaats daarvan Positie langs membraan en een dieptepositie.</p><p>3D-cellen hebben een gladde halve bol aan de achterkant en een vlakke doorsnede met oorspronkelijke kern en organellen aan de voorkant. Volumediepte verandert de diepte. Afgerond volume en reliëf zijn schematische geometrieopties voor SVG-modellen; dit zijn geen voorspellingen van de atomaire eiwitstructuur.</p><p>Bewaar in eigen bibliotheek maakt modellen opnieuw beschikbaar in deze browser op dit apparaat. Ondersteunde geselecteerde modellen kunnen als GLB worden geëxporteerd. Een 3D-variant houdt de ID van zijn 2D-bron bij om duplicaten te voorkomen. Latere 2D-bewerkingen bouwen een bestaande 3D-variant niet automatisch opnieuw op. Verwijder die 3D-variant en voer de omzetting opnieuw uit om hem te vernieuwen.</p>`,
      ],
      [
        "three-membrane",
        "8. Het 3D-membraan toevoegen en bewerken",
        `<p>Zet Eigenschappen → Membraan → Membraan tonen aan of kies het gereedschap Membraan. In een nieuwe scène staat het standaard uit. Dikte, Diepte en Vervaging achterzijde bepalen het uiterlijk. Lipidekoppen bedekken de oppervlakken; dunne, gepaarde staarten staan alleen langs de fysieke buitenrand, niet overal in de diepte.</p><p>Kies Béziercurve bewerken voor ankers en handvatten. Sleep deze om het membraan te buigen. Curvepunt toevoegen splitst de kromme; gekoppelde eiwitten volgen de vorm. Doorsnede verandert het zichtbare snijvlak. Vanuit een zij- of bovenaanzicht kan de rand dun lijken: draai de camera om hem te inspecteren.</p><p>Voor ondersteunde eiwitten en geïmporteerde structuren schakel je met Koppelen aan membraan / Membraan losmaken de verankering. Importmodellen gebruiken hun modelorigine als handmatig anker. Controleer zelf oriëntatie, schaal en de transmembraangrens. Het referentiekanaal heeft een membraanopening; willekeurige importmodellen krijgen niet automatisch een passende porie.</p><p>Conformatie is een schematisch IgG-scharniergereedschap: selecteer IgG, kies Conformatie, selecteer een Fab-arm en verander de scharnierhoek. Dit is geen algemene eiwit-rigging of moleculaire dynamica.</p>`,
      ],
      [
        "pdb",
        "9. SVG, GLB, PDB en mmCIF importeren",
        `<p>Klik op + in de bibliotheek. Importeer in 2D een zelfstandige SVG; in 3D zijn SVG, GLB, PDB, CIF en mmCIF beschikbaar. De bestandslimiet is 30 MB. Gebruik onafhankelijke vector-SVG’s zonder scripts of externe afbeeldingen. Een SVG-import in 3D begint als vlak object; gebruik Bouw 3D-volume wanneer die knop beschikbaar is.</p><h3>Een structuur uit RCSB PDB ophalen</h3><ol><li>Kies in 3D de tab PDB en zoek op molecuulnaam of PDB-ID.</li><li>Open een resultaat. Kies biologische assemblage 1 of de asymmetrische eenheid.</li><li>Haal de structuur op. Probeer de asymmetrische eenheid als de assemblage ontbreekt.</li><li>Inspecteer de draaibare voorvertoning en selecteer alleen de benodigde ketens.</li><li>Kies van der Waals-atoombollen of de CA/P-ruggengraat.</li><li>Voeg de geselecteerde ketens toe en controleer schaal, oriëntatie en eventueel het membraananker.</li></ol><p>Sommige basismoleculen tonen Experimentele structuur met een gecontroleerde PDB-referentie en een RCSB-link. Dit kunnen fragmenten, complexen of een verwante soort/isotype zijn. Controleer soort, allel, peptide en ketensamenstelling. Een referentie is geen automatische exacte identificatie van de cartoon. Andere moleculen bieden zoeken bij RCSB.</p><p>Coördinaten worden omgerekend van Å naar nm. Ontbrekende domeinen worden niet gereconstrueerd. De app simuleert geen moleculaire dynamica en berekent geen moleculair oplosmiddeloppervlak. RCSB-zoeken en ophalen vereisen internet; geïmporteerde coördinaten worden in het project bewaard.</p>`,
      ],
      [
        "styles",
        "10. Illustratiestijlen",
        `<p>Open Eigenschappen → Stylesheet. De volgorde is Default, UMC Utrecht, Nordic Light, Nordic Dark, EFI, Illustrated Light en Dark Presentation. Nieuwe projecten gebruiken Default. Een stijl verandert de illustratiekleuren; de programma-interface behoudt de UMC Utrecht-opmaak.</p><p>Met de kleurvakken wijzig je rollen zoals koppen, staarten, receptoren, HLA, antistoffen, achtergrond en labels. Eigen objectkleuren kunnen voorrang hebben; Stijlkleur herstelt de stijlrol van dat object. Importeren en JSON-export maken hergebruik van een stylesheet mogelijk. Bewaar het project na het maken van een eigen palet.</p>`,
      ],
      [
        "animate",
        "11. Een bewegend molecuul animeren: volledig voorbeeld",
        `<ol><li>Voeg in 3D een molecuul toe en selecteer het. Zet Duur op 8 seconden.</li><li>Open Eigenschappen → <b>Animatie en render</b>. Kies 24 fps, Startframe 1 en Eindframe 192.</li><li>Kies <b>Geselecteerd object</b> bij Keyframe voor. Laat Automatische keyframes eerst uit terwijl je de beginposes maakt.</li><li>Zet de tijdlijn op 0 seconden. Stel de beginpositie in en kies Keyframe invoegen.</li><li>Zet de tijdlijn op 4 seconden. Verplaats of draai het molecuul en voeg opnieuw een keyframe toe.</li><li>Klik op afspelen. De beweging tussen de poses wordt automatisch berekend.</li><li>Sleep de tijdlijn om tussenframes te inspecteren.</li><li>Wijzig in de keyframelijst het framenummer voor andere timing, kies interpolatie of verwijder een keyframe met ×.</li></ol><p><b>Let op de volgorde:</b> verplaats eerst de tijd, wijzig daarna de pose en voeg dan de key toe. Door de tijdlijn te verplaatsen worden bestaande keys geëvalueerd en kan een nog niet vastgelegde pose verdwijnen. Na de beginopzet legt Automatische keyframes volgende interactieve camera-/objecttransformaties vast. Voeg na andere eigenschapswijzigingen expliciet een key toe als je die pose zeker wilt bewaren.</p><table><tr><th>Interpolatie</th><th>Resultaat</th></tr><tr><td>Constant</td><td>De eerdere pose vasthouden tot de volgende key.</td></tr><tr><td>Lineair</td><td>Waarden met constante snelheid tussen keys veranderen.</td></tr><tr><td>Vloeiend · Bézier</td><td>De beweging rustig laten beginnen en eindigen.</td></tr></table><p>De interpolatie van een key bepaalt het daaropvolgende segment. Dit is een Blender-achtige keyframewerkwijze met vloeiende overgangen, geen volledige Blender F-curve-editor, NLA, constraint- of riggingsysteem. De objectbaan volgt de vastgelegde posities; botsingen of fysische beweging worden niet gesimuleerd.</p>`,
      ],
      [
        "camera",
        "12. Camera-acties en gecombineerde animatie",
        `<p>Kies Alleen camera om het zicht vast te leggen zonder objectposes op te slaan. Draai, verschuif of zoom op de begintijd naar het eerste zicht en voeg een key toe. Verplaats de tijd, verander het zicht en voeg een volgende key toe. Object- en camerasporen kunnen naast elkaar bestaan. Scène en camera legt alle objectposes en het zicht samen vast; gebruik aparte doelen voor onafhankelijke timing.</p><p>Focus selectie kiest het doel. Camera &amp; focus → Follow-me verplaatst de camera met het anker; Kijk naar focus richt op het anker; Vrije camera heft dat volgen op.</p><table><tr><th>Camera-actie</th><th>Beweging over het renderbereik</th></tr><tr><td>Orbit 360°</td><td>Een volledige ronde om het huidige cameradoel.</td></tr><tr><td>Dolly naar focus</td><td>De camera halverwege richting het doel verplaatsen.</td></tr><tr><td>Zoom naar focus</td><td>De camerazoom verdubbelen zonder dollybeweging.</td></tr><tr><td>Pan horizontaal</td><td>Camera en doel samen horizontaal verplaatsen.</td></tr><tr><td>Object 360° draaien</td><td>Een volledige draaiing voor het geselecteerde object maken.</td></tr></table><p>Stel eerst het zicht, doel en renderbereik in. Een camera-actie vervangt camera-only keys binnen dat bereik; objectsporen blijven behouden. Gebruik Ongedaan maken om vorige keys te herstellen. Herhalen speelt het renderbereik opnieuw af. Frame 1 is tijdstip nul; bij 24 fps is frame 97 gelijk aan 4 seconden.</p>`,
      ],
      [
        "export",
        "13. Export voor figuren, Office en video",
        `<p>Download eerst een bewerkbare Project-kopie. Afbeeldingen en video’s zijn eindproducten, geen vervanging voor het project. Stel vóór export de stijl en Labels in.</p><table><tr><th>Formaat</th><th>Gebruik en beschikbaarheid</th></tr><tr><td>PNG</td><td>Online/lokaal. Rasterafbeelding van 1920 of 3840 px breed, eventueel transparant. 2D exporteert het blad; 3D het huidige zicht.</td></tr><tr><td>SVG</td><td>Online/lokaal. Het volledige native 2D-blad. In 3D alleen de geselecteerde bronvector, niet de volledige gerenderde scène.</td></tr><tr><td>EMF / WMF</td><td>Lokale Inkscape-exporter. Geschikt voor PowerPoint/Word. 2D blijft waar ondersteund vector; 3D bevat een ingesloten rasterafbeelding.</td></tr><tr><td>MP4 / AVI</td><td>Lokale FFmpeg-exporter. MP4 gebruikt H.264, AVI Motion JPEG. Renderinstellingen bepalen bereik, snelheid en afmetingen.</td></tr><tr><td>GIF</td><td>Lokaal. 12 fps, 800 px breed, maximaal 15 seconden, herhalend.</td></tr><tr><td>WebM</td><td>Online/lokaal als de browser opname ondersteunt. Opname in werkelijke tijd; houd de tab actief voor betrouwbare opname.</td></tr><tr><td>PNG-framereeks</td><td>Online/lokaal. ZIP met een genummerde afbeelding voor ieder gekozen frame, bruikbaar in externe videobewerking.</td></tr></table><p><b>Fonts:</b> bij EMF/WMF kan tekst worden omgezet naar vectorcontouren. Dit bewaart de lettervorm maar sluit geen bewerkbare fonts in. Bewaar het project voor tekstbewerking. Office-versies kunnen kleurverlopen vereenvoudigen; SVG of PNG kan geschikter zijn als het uiterlijk belangrijker is dan metabestandbewerking.</p><h3>Renderinstellingen</h3><ol><li>Kies onder Animatie en render 12, 24, 25, 30, 50 of 60 fps.</li><li>Stel Startframe, Eindframe en Framestap in. Stap 1 gebruikt ieder frame.</li><li>Kies renderbreedte (320–3840) en hoogte (240–2160). Gebruik even afmetingen voor gangbare video-encoders.</li><li>Open Exporteren en controleer de instellingen. Kies PNG-reeks, WebM of een lokaal videoformaat.</li><li>Wacht op voltooiing; gebruik Annuleren wanneer het voortgangspaneel die optie toont.</li></ol><p>Er kunnen maximaal 1801 frames per opdracht worden uitgevoerd. Een framestap groter dan 1 slaat frames over. PNG-bestandsnamen behouden de oorspronkelijke framenummers; gecodeerde video speelt ze op de gekozen fps af en wordt daardoor korter. PNG en lokale video renderen de gekozen frames afzonderlijk; WebM neemt in werkelijke tijd op. Video-instellingen veranderen niet de aparte formaatkeuze voor stilstaande afbeeldingen.</p><p>Uitgeschakelde lokale exportknoppen op GitHub Pages zijn normaal. Open een gedownload .immuno-project in de lokale versie voor EMF/WMF of MP4/AVI/GIF. Voeg het bestand in Word of PowerPoint in via Invoegen → Afbeeldingen, of Invoegen → Video voor een ondersteund filmformaat.</p>`,
      ],
      [
        "save",
        "14. Opslaan, heropenen en overzetten",
        `<p>De editor slaat automatisch op in de browseropslag van dit apparaat. Wacht op de bewaarindicator. Dit is geen cloudaccount of gedeelde projectmap. Online en lokaal hebben afzonderlijke browseropslag; een andere browser of computer ziet je project niet automatisch.</p><ol><li>Klik op Project voor een bewerkbaar <code>.immuno</code>-bestand.</li><li>Bewaar genummerde versies vóór grote veranderingen.</li><li>Kies Openen en selecteer het bestand om het project met ingesloten objecten en animatiekeys te herstellen.</li><li>Download in de ene versie en open in de andere om tussen online en lokaal te wisselen.</li><li>Download vóór Nieuw → Lege scène starten het huidige project als je het afzonderlijk wilt bewaren.</li></ol><p>Browser-/sitegegevens wissen kan autosaves en de eigen modellenbibliotheek verwijderen. Bestandskopieën blijven je overdraagbare reservekopie. Ongedaan maken/Opnieuw zijn bedoeld voor recente bewerkingen; de beperkte undo-geschiedenis is geen versiearchief.</p>`,
      ],
      [
        "shortcuts",
        "15. Sneltoetsen",
        `<table><tr><th>Toetsen</th><th>Actie</th></tr><tr><td>Ctrl/Cmd+Z</td><td>Ongedaan maken</td></tr><tr><td>Ctrl/Cmd+Shift+Z</td><td>Opnieuw</td></tr><tr><td>Ctrl/Cmd+A</td><td>Alles selecteren in 2D</td></tr><tr><td>Ctrl/Cmd+C / V / D</td><td>Kopiëren / plakken / dupliceren in 2D</td></tr><tr><td>Ctrl/Cmd+G / Shift+Ctrl/Cmd+G</td><td>Groeperen / losmaken in 2D</td></tr><tr><td>Pijltje / Shift+pijltje</td><td>2D-selectie 1 / 10 eenheden verplaatsen</td></tr><tr><td>Delete</td><td>Selectie verwijderen als het blad/de scène focus heeft</td></tr><tr><td>Escape</td><td>Dialoog sluiten; in 2D ook terug naar Selecteren en deselecteren</td></tr></table><p>Tekensneltoetsen werken doorgaans niet op de tekening als je in een tekst-, getal- of keuzeveld typt. Klik eerst op het blad of de scène.</p>`,
      ],
      [
        "troubleshoot",
        "16. Problemen oplossen en beperkingen",
        `<dl><dt>Ik kan een element niet verplaatsen.</dt><dd>Controleer modus en gereedschap. Selecteer het, ontgrendel in Eigenschappen en kies Verplaatsen. In 3D draait slepen over lege ruimte de camera.</dd><dt>Een element zit achter een ander.</dt><dd>Selecteer via de scènelijst in Eigenschappen, zet zichtbaarheid aan en pas stapelvolgorde of diepte aan.</dd><dt>Mijn 2D-tekening ontbreekt in 3D.</dt><dd>Wisselen converteert niet automatisch. Kies 3D uit 2D-tekening. Alleen geschikte vectoren en membranen worden omgezet; tekst en native primitieve vormen worden niet allemaal direct geconverteerd.</dd><dt>Mijn 3D-variant toont oude 2D-inhoud.</dt><dd>Bestaande varianten blijven behouden. Verwijder de betreffende variant en genereer opnieuw uit de bijgewerkte bron.</dd><dt>Het membraan ontbreekt.</dt><dd>Zet Membraan tonen aan in 3D of teken/converteer een membraan in 2D. De twee modi hebben afzonderlijke membraaninhoud.</dd><dt>De animatie springt of een pose verdwijnt.</dt><dd>Controleer keyframe-doel, timing en interpolatie. Leg beginpose en iedere gewijzigde pose vast. Tijdlijnverschuiven leest bestaande keys; gebruik Ongedaan maken voor een verloren niet-vastgelegde bewerking.</dd><dt>Een PDB-model bevat extra kopieën.</dt><dd>Controleer assemblage en ketenselectie. Importeer alleen de benodigde ketens; niet iedere keten hoort bij jouw bedoelde figuur.</dd><dt>Een lokale exporter ontbreekt.</dt><dd>Start de lokale versie en controleer Inkscape/FFmpeg-ondersteuning. Gebruik online SVG/PNG, WebM of PNG-frames.</dd><dt>De app wordt traag.</dt><dd>Verminder complexe volumes of geïmporteerde atomen, gebruik ruggengraatweergave en test eerst een kort bereik op lage resolutie.</dd></dl><p>Alle 190 basiselementen zijn gecontroleerd op geldige eindige 3D-geometrie. Een schematisch volume bewijst echter geen biologische identiteit. Automatische reconstructie van ontbrekende regio’s, volledige moleculaire oppervlakken, algemene rigging en moleculaire dynamica zijn niet beschikbaar.</p>`,
      ],
    ],
  },
};

const css = `:root{font:16px/1.65 system-ui,sans-serif;color:#002b49;background:#edf3f7}*{box-sizing:border-box}body{margin:0}header{background:#002b49;color:white;padding:38px max(24px,calc((100% - 1100px)/2))}header p{color:#cde2ef}h1{font-size:2.2rem;line-height:1.2;margin:12px 0}a{color:#0077b6;text-underline-offset:3px}header a{color:#fff}nav.actions{display:flex;gap:20px;flex-wrap:wrap;align-items:center}button{background:#0077b6;color:white;border:0;border-radius:5px;padding:10px 16px;font:inherit;cursor:pointer}.layout{max-width:1150px;margin:auto;display:grid;grid-template-columns:240px minmax(0,1fr);gap:35px;padding:30px 24px}aside{position:sticky;top:20px;align-self:start;max-height:90vh;overflow:auto;font-size:.88rem}aside a{display:block;padding:6px 0}article{background:white;border:1px solid #d8e3ea;padding:16px 36px 45px;min-width:0}section{scroll-margin-top:20px;border-bottom:1px solid #d8e3ea;padding:12px 0 28px}h2{font-size:1.5rem;line-height:1.3;margin-top:28px}h3{font-size:1.12rem}li{margin:8px 0}table{border-collapse:collapse;width:100%;font-size:.92rem;margin:20px 0}th,td{border:1px solid #d8e3ea;padding:10px;text-align:left;vertical-align:top}th{background:#e8f3fa}dt{font-weight:700;margin-top:20px}dd{margin:4px 0 14px}code{background:#edf3f7;padding:2px 4px;overflow-wrap:anywhere}footer{padding:24px;text-align:center;font-size:.85rem}@media(max-width:800px){.layout{display:block;padding:15px}aside{position:static;max-height:none;margin-bottom:20px}article{padding:10px 20px}h1{font-size:1.8rem}}@media print{html{font-size:10pt;background:white}header{background:white;color:#002b49;padding:0}header p{color:#002b49}.actions,aside,footer{display:none!important}.layout{display:block;padding:0;max-width:none}article{border:0;padding:0}section{break-before:auto}h2,h3{break-after:avoid}tr{break-inside:avoid}a{color:inherit}body{margin:12mm}table{font-size:9pt}}`;
await mkdir("public/manual", { recursive: true });
for (const [lang, m] of Object.entries(manuals)) {
  const other = lang === "en" ? "nl" : "en";
  const html = `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${m.title}</title><link rel="icon" href="../immunostudio-icon.svg"><style>${css}</style></head><body><header><div>IMMUNOSTUDIO · USER DOCUMENTATION</div><h1>${m.title}</h1><p>${m.subtitle}</p><nav class="actions"><a href="../">${m.back}</a><a href="${other}.html" lang="${other}">${m.other}</a><button onclick="window.print()">${m.print}</button></nav></header><div class="layout"><aside aria-label="${m.contents}"><b>${m.contents}</b>${m.sections.map(([id, title]) => `<a href="#${id}">${title}</a>`).join("")}</aside><article>${m.sections.map(([id, title, body]) => `<section id="${id}"><h2>${title}</h2>${body}</section>`).join("")}</article></div><footer>ImmunoStudio · 2 November 2026 · <a href="${other}.html">${m.other}</a></footer></body></html>`;
  await writeFile(`public/manual/${lang}.html`, html);
}
console.log("Generated English and Dutch manuals, 16 sections each.");
